from PIL import Image
from collections import deque
im=Image.open('sheet.png');w,h=im.size;p=im.getchannel('A').tobytes()
for threshold in [8,32,64,128]:
 seen=bytearray(w*h); comps=[]
 for i,a in enumerate(p):
  if a<threshold or seen[i]:continue
  seen[i]=1;q=deque([i]);count=0;x0=w;y0=h;x1=y1=0
  while q:
   j=q.popleft();count+=1;x=j%w;y=j//w;x0=min(x0,x);y0=min(y0,y);x1=max(x1,x+1);y1=max(y1,y+1)
   for yy in range(max(0,y-1),min(h,y+2)):
    for xx in range(max(0,x-1),min(w,x+2)):
     k=yy*w+xx
     if p[k]>=threshold and not seen[k]:seen[k]=1;q.append(k)
  if count>5000:comps.append((count,(x0,y0,x1,y1)))
 print(threshold,len(comps),sorted(comps,key=lambda c:(c[1][1]//230,c[1][0])))
